CREATE TABLE users_new (
    id TEXT NOT NULL,
    username VARCHAR(255) NOT NULL,
    password_hash VARCHAR(512) NOT NULL,
    display_name VARCHAR(255) NOT NULL,
    role VARCHAR(50) NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT,
    tenant_id TEXT,
    email VARCHAR(255),
    CONSTRAINT PK_USERS_NEW PRIMARY KEY (id),
    CONSTRAINT fk_users_new_tenant FOREIGN KEY (tenant_id) REFERENCES tenants(id)
);
INSERT INTO users_new (id, username, password_hash, display_name, role, created_at, updated_at, tenant_id, email)
    SELECT id, username, password_hash, display_name, role, created_at, updated_at, tenant_id, email FROM users;
DROP TABLE users;
ALTER TABLE users_new RENAME TO users;
CREATE UNIQUE INDEX uq_users_tenant_username ON users(tenant_id, username);
